.site-footer { background: #0d0d0d; border-top: 1px solid var(--line); padding: 2rem 0; margin-top: 2rem; }
.footer-row { display: flex; justify-content: space-between; gap: 1rem; flex-wrap: wrap; color: var(--muted); }
